#include <bits/stdc++.h>
using namespace std;

struct State {
    int xp, yp, xv, yv;
    bool turn;

    bool operator==(const State& other) const {
        return xp == other.xp && yp == other.yp &&
               xv == other.xv && yv == other.yv &&
               turn == other.turn;
    }
};

struct StateHash {
    size_t operator()(const State& s) const {
        size_t h = 0;
        auto combine = [&](int value) {
            h ^= hash<int>{}(value) + 0x9e3779b9 + (h << 6) + (h >> 2);
        };
        combine(s.xp);
        combine(s.yp);
        combine(s.xv);
        combine(s.yv);
        combine(s.turn);
        return h;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    State initial;
    if (!(cin >> initial.xp >> initial.yp >> initial.xv >> initial.yv))
        return 0;
    initial.turn = true;

    queue<State> q;
    unordered_set<State, StateHash> visited;

    auto push = [&](const State& state) {
        if (visited.insert(state).second)
            q.push(state);
    };

    push(initial);

    while (!q.empty()) {
        State s = q.front();
        q.pop();

        if (s.xp == 0 && s.yp == 0) {
            cout << "Polycarp";
            return 0;
        }

        if (s.xv == 0 && s.yv == 0) {
            cout << "Vasiliy";
            return 0;
        }

        if (s.turn) {
            if (s.xp > 0 && (s.xp - 1 != s.xv || s.yp != s.yv))
                push({s.xp - 1, s.yp, s.xv, s.yv, false});

            if (s.yp > 0 && (s.yp - 1 != s.yv || s.xp != s.xv))
                push({s.xp, s.yp - 1, s.xv, s.yv, false});
        } else {
            if (s.xv > 0 && (s.xp != s.xv - 1 || s.yp != s.yv))
                push({s.xp, s.yp, s.xv - 1, s.yv, true});

            if (s.yv > 0 && (s.yp != s.yv - 1 || s.xv != s.xp))
                push({s.xp, s.yp, s.xv, s.yv - 1, true});

            if (s.xv > 0 && s.yv > 0 &&
                s.yp != s.yv - 1 && s.xv - 1 != s.xp)
                push({s.xp, s.yp, s.xv - 1, s.yv - 1, true});
        }
    }

    return 0;
}

